    int n, i, first = -1;
    long long sum = 0;
    long long acc = 0;

    if (scanf("%d", &n) != 1)
        return 0;

    for (i = 1; i <= n; i++) {
        long long x;
        if (scanf("%lld", &x) != 1)
            return 0;
        sum += x;
        if (first == -1) {
            long long nxt = acc + x;
            if (nxt > (long long)INT_MAX || nxt < (long long)INT_MIN)
                first = i;
            else
                acc = nxt;
        }
    }

    printf("sum: %lld\n", sum);
    if (first == -1)
        printf("overflow: safe\n");
    else
        printf("overflow: %d\n", first);
    return 0;
}

