import sys

UPPER_BASE = ord("A")
LOWER_BASE = ord("a")


def swap_case(text):
    out = []
    for ch in text:
        if "A" <= ch <= "Z":
            out.append(chr(ord(ch) - UPPER_BASE + LOWER_BASE))
        elif "a" <= ch <= "z":
            out.append(chr(ord(ch) - LOWER_BASE + UPPER_BASE))
        else:
            out.append(ch)
    return "".join(out)


def rot13(text):
    out = []
    for ch in text:
        if "A" <= ch <= "Z":
            out.append(chr((ord(ch) - UPPER_BASE + 13) % 26 + UPPER_BASE))
        elif "a" <= ch <= "z":
            out.append(chr((ord(ch) - LOWER_BASE + 13) % 26 + LOWER_BASE))
        else:
            out.append(ch)
    return "".join(out)


def main():
    line = sys.stdin.readline()
    s = line.strip()
    if not s:
        return

    upper = sum(1 for ch in s if "A" <= ch <= "Z")
    lower = sum(1 for ch in s if "a" <= ch <= "z")
    checksum = sum(ord(ch) for ch in s)

    print(swap_case(s))
    print(rot13(s))
    print(f"upper: {upper} lower: {lower}")
    print(f"checksum: {checksum}")


if __name__ == "__main__":
    main()

