import sys


def trunc_div(a, b):
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def main():
    text = sys.stdin.readline().strip()
    if not text:
        return

    n = len(text)
    pos = 0

    def skip_spaces():
        nonlocal pos
        while pos < n and text[pos] == " ":
            pos += 1

    def factor():
        nonlocal pos
        skip_spaces()
        if pos < n and text[pos] == "(":
            pos += 1
            value = expr()
            skip_spaces()
            if pos < n and text[pos] == ")":
                pos += 1
            return value

        value = 0
        while pos < n and text[pos].isdigit():
            value = value * 10 + int(text[pos])
            pos += 1
        return value

    def term():
        nonlocal pos
        value = factor()
        while True:
            skip_spaces()
            if pos < n and text[pos] in "*/":
                op = text[pos]
                pos += 1
                rhs = factor()
                if op == "*":
                    value *= rhs
                else:
                    value = trunc_div(value, rhs)
            else:
                return value

    def expr():
        nonlocal pos
        value = term()
        while True:
            skip_spaces()
            if pos < n and text[pos] in "+-":
                op = text[pos]
                pos += 1
                rhs = term()
                value = value + rhs if op == "+" else value - rhs
            else:
                return value

    print(expr())


if __name__ == "__main__":
    main()

